export interface ContactInput {
  name: string
  email: string
  message: string
}

export type ContactErrors = Partial<Record<keyof ContactInput, string>>

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/

export function normalizeContact(input: Record<string, unknown> | null | undefined): ContactInput {
  const pick = (key: string) => {
    const value = input?.[key]
    return typeof value === 'string' ? value : ''
  }
  return { name: pick('name'), email: pick('email'), message: pick('message') }
}

export function validateContact(input: ContactInput): ContactErrors {
  const name = input.name.trim()
  const email = input.email.trim()
  const message = input.message.trim()
  const errors: ContactErrors = {}
  if (!name) errors.name = 'Name is required.'
  if (!email) errors.email = 'Email is required.'
  else if (!EMAIL_RE.test(email)) errors.email = 'Enter a valid email address.'
  if (message.length < 20) errors.message = 'Message must be at least 20 characters.'
  return errors
}

export function successMessage(name: string): string {
  return `Thanks, ${name.trim()}! Your message has been sent.`
}
EOF
