// Handles the no-JavaScript form post to /contact: the result is attached to
// the event context and rendered by the contact page.
export default defineEventHandler(async (event) => {
  if (event.method !== 'POST') return
  const path = getRequestURL(event).pathname.replace(/\/+$/, '')
  if (path !== '/contact') return
  const body = await readBody<Record<string, unknown>>(event)
  const values = normalizeContact(body)
  const errors = validateContact(values)
  event.context.contactForm = {
    values,
    errors,
    success: Object.keys(errors).length === 0 ? successMessage(values.name) : null,
  }
})
